head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "Url(필수) 파라미터로 팝업에 표시할 페이지의 URL 경로를 설정합니다.",
        "options(필수) 파라미터로 팝업의 옵션을 JSON 객체로 설정합니다.",
        "options.id(선택) 파라미터로 팝업의 ID 를 설정합니다.",
        "options.id(선택) 파라미터 생략 시, 기본값 'ppo1' 로 동작합니다.",
        "options.type(선택) 파라미터를 'browserPopup' 으로 설정하면, window.open() 을 사용하여 프로세스가 분리된 독립창(Window)으로 팝업을 생성하며 부모 화면에 종속되지 않고 팝업 위치를 자유롭게 움직일 수 있습니다.",
        "options.type(선택) 파라미터를 'iframePopup' 으로 설정하면, 팝업을 호출한 화면에 iFrame 방식의 내부 팝업을 생성하며 부모 화면에 종속됩니다.",
        "options.type(선택) 파라미터를 'wframePopup' 으로 설정하면, 팝업을 호출한 화면에 wFrame 방식의 내부 팝업을 생성하며 부모 화면에 종속됩니다.",
        "options.type(선택) 파라미터를 'pageFramePopup' 으로 설정하면, 팝업을 호출한 화면에 pageFrame 방식의 내부 팝업을 생성하며 부모 화면에 종속됩니다.",
        "options.type(선택) 파라미터 생략 시, 기본값 'browserPopup' 으로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.popupUrl = "/sample/common_link/p_openPopup_popup.xml";



scwin.out = function (str) {
    wf_body_bottom.getObj("scwin").setReturnValue(str);
};



// 이전 테스트 팝업 정리 (내부 팝업을 정리했으면 true 반환)
scwin.closeAllPopup = function () {
    let list = $p.getAllPopupList().slice();
    let closedInner = false;
    for (let i = 0; i < list.length; i++) {
        let pw = list[i].popupWin;
        try {
            if (pw && typeof pw.forceClose === "function") {
                pw.forceClose();
                closedInner = true;
            } else if (pw && typeof pw.close === "function") {
                pw.close();
            }
        } catch (e) {}
    }
    return closedInner;
};



// 이전 팝업 정리 후 openPopup 실행
// (내부 팝업 정리는 비동기로 끝나므로 300ms 후 연다. 클릭 직후 5초 이내라 browserPopup 도 사용자 동작으로 처리됨)
scwin.runOpenPopup = function (optionList, callback, delay) {
    let fn = function () {
        for (let i = 0; i < optionList.length; i++) {
            $p.openPopup(scwin.popupUrl, optionList[i]);
        }
        if (callback) setTimeout(callback, delay || 1500);
    };
    if (scwin.closeAllPopup()) {
        setTimeout(fn, 300);
    } else {
        fn();
    }
};



scwin.btn_openPopup_onclick = function () {
    let id = par_id.getValue();
    let type = par_type.getValue();

    let options = { width: "500px", height: "300px", popupName: "openPopup 팝업" };
    if (id !== "") options.id = id;
    if (type !== "") options.type = type;

    scwin.runOpenPopup([options], scwin.printResult);
};



// 팝업 안 페이지의 닫기 버튼 조회 (페이지 로드 확인용)
scwin.closeBtnOf = function (pw) {
    try {
        if (pw.options.type === "browser") return pw.popupWin.document.getElementById("mf_btn_close");
        let el = pw.popupWin.render;
        let ifr = el.querySelector("iframe");
        if (ifr) return ifr.contentDocument.getElementById("mf_btn_close");
        return el.querySelector(".w2window_content [id$='_btn_close']");
    } catch (e) {
        return null;
    }
};



scwin.isShown = function (el) {
    return !!el && el.offsetWidth > 0 && el.offsetHeight > 0;
};



// 팝업 안 페이지 로드(닫기 버튼 표시)를 최대 5초 기다린 뒤 판정 출력
scwin.printResult = function () {
    let list = $p.getAllPopupList();
    let pw = list[list.length - 1];
    if (!pw || !pw.popupWin) {
        scwin.out("팝업 생성 : false");
        return;
    }
    let count = 0;
    let wait = function () {
        if (scwin.isShown(scwin.closeBtnOf(pw)) || count++ >= 50) {
            scwin.printPopup(pw);
        } else {
            setTimeout(wait, 100);
        }
    };
    wait();
};



// validation 1~9 판정 출력 (팝업 ID / 생성 방식 / 표시 페이지 / 부모 화면 종속 여부 / 타이틀·크기 / 페이지 로드)
scwin.printPopup = function (pw) {
    let popupId = pw.options.id;
    let closeShown = scwin.isShown(scwin.closeBtnOf(pw));
    if (pw.options.type === "browser") {
        let url = "";
        let title = "";
        try {
            url = pw.popupWin.location.pathname + pw.popupWin.location.search;
            title = pw.popupWin.document.title;
        } catch (e) {}
        let innerCount = document.querySelectorAll(".w2popup_window").length;
        scwin.out("팝업 ID : " + popupId + " / 생성 방식 : window.open() 독립창 / 주소 : " + url
            + " / 부모 화면 내부 팝업 수 : " + innerCount + " / 창 제목 : " + title + " / 닫기 버튼 표시 : " + closeShown);
    } else {
        let el = pw.popupWin.render;
        let frameEl = el ? el.querySelector(".w2window_content > *") : null;
        let frameKind = frameEl ? frameEl.className.split(" ")[0] : "없음";
        let titleEl = el ? document.getElementById(el.id + "_header_title") : null;
        let r = el.getBoundingClientRect();
        scwin.out("팝업 ID : " + popupId + " / 팝업 DOM id : " + el.id + " / 생성 방식 : 부모 화면 내부 " + frameKind + " / 표시 페이지 : " + pw.popupWin.options.src
            + " / 부모 body 소속 : " + document.body.contains(el) + " / 타이틀 : " + (titleEl ? titleEl.textContent : "")
            + " / 크기 : " + Math.round(r.width) + " x " + Math.round(r.height) + " / 닫기 버튼 표시 : " + closeShown);
    }
};
